const $=s=>document.querySelector(s);const selection=new Map();let current=null;const cats=['Todos','IA & criação','Gestão & inteligência','Operação & execução','Relacionamento'];
$('#filters').innerHTML=cats.map((c,i)=>`<button class="${i?'':'active'}" data-filter="${c}">${c}</button>`).join('');
const positions=apps.map((a,i)=>{const angle=(-90+i*360/apps.length)*Math.PI/180;return {x:50+38*Math.cos(angle),y:48+36*Math.sin(angle)}});
$('#nodes').innerHTML=apps.map((a,i)=>`<button class="node" data-id="${a.id}" style="left:${positions[i].x}%;top:${positions[i].y}%;--c:${a.color};--delay:-${i*.4}s" aria-label="Explorar ${a.name}"><span class="icon" aria-hidden="true">${a.icon}</span><strong>${a.name}</strong><small>${a.category}</small></button>`).join('');
$('#connections').innerHTML=positions.map(p=>`<line x1="500" y1="297.6" x2="${p.x*10}" y2="${p.y*6.2}"/>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function sync(){ $('#count').textContent=selection.size;clPre();document.querySelectorAll('.node').forEach(n=>n.classList.toggle('selected',selection.has(n.dataset.id))); }
function selectApp(a,on){if(on)selection.set(a.id,[...a.modules]);else selection.delete(a.id);sync()}
function show(d){document.querySelectorAll('dialog[open]').forEach(x=>x.close());d.showModal();d.scrollTop=0}
function closeButton(){return '<button class="close" aria-label="Fechar">×</button>'}
// Vitrine: o sistema escolhido dá um pulso na mandala e a página rola até os detalhes dele
const calm=matchMedia('(prefers-reduced-motion: reduce)').matches,glide=calm?'auto':'smooth';
const spots=[[66,12],[26,30],[76,50],[24,70],[64,88]];
const check='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12 5 5 9-10"/></svg>';
const lock='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>';
function pulse(el){el.classList.remove('launch');void el.offsetWidth;el.classList.add('launch')}
function openApp(id){pulse(document.querySelector(`.node[data-id="${id}"]`));setTimeout(()=>{showApp(id);$('#showcase').scrollIntoView({behavior:glide})},calm?0:380)}
function backToMandala(){$('.universe').scrollIntoView({behavior:glide,block:'center'});const n=document.querySelector(`.node[data-id="${current.id}"]`);setTimeout(()=>pulse(n),calm?0:650)}
function showApp(id){const a=apps.find(a=>a.id===id),s=$('#showcase');current=a;
document.querySelectorAll('.node').forEach(n=>n.classList.toggle('current',n.dataset.id===id));
s.innerHTML=`<div class="sc-nav"><button class="back" id="to-mandala">← Voltar<span> para a mandala</span></button><button class="back go" id="go">Acessar<span> o ${a.name}</span></button></div>
<div class="sc-head"><span class="eyebrow">${a.category.toUpperCase()} · ${a.name.toUpperCase()}</span><h2>${a.headline[0]}<br><em>${a.headline[1]}</em></h2><p>${a.description}</p></div>
<div class="sc-grid"><ol class="steps">${a.steps.map(([t,d],i)=>`<li style="--i:${i}"><b>${i+1}</b><div><h3>${t}</h3><p>${d}</p></div></li>`).join('')}</ol>
<div class="orbitvis" aria-hidden="true"><i class="ring"></i><i class="ring"></i><i class="ring"></i><i class="sweep"></i><div class="hub">${a.icon}</div>${a.chips.map((c,i)=>`<span class="chip" style="--i:${i};left:${spots[i][0]}%;top:${spots[i][1]}%"><em>${check}</em>${c}</span>`).join('')}</div></div>
<div class="sc-foot"><div><h3>O que faz sentido para sua empresa?</h3><div class="modules">${a.modules.map((m,i)=>`<label class="module"><input type="checkbox" data-module="${i}" ${selection.get(a.id)?.includes(m)?'checked':''}><span>${m}</span></label>`).join('')}</div><p class="note">PARA QUEM · ${a.audience}</p></div>
<div class="actions"><button class="primary" id="entire">Adicionar aplicação completa</button><button id="live">Ver funcionando ao vivo</button><a href="https://${a.url}" target="_blank" rel="noopener">Abrir em nova aba ↗</a></div></div>`;
s.hidden=false;$('#to-mandala').onclick=backToMandala;
const boxes=s.querySelectorAll('[data-module]');
$('#entire').onclick=()=>{selectApp(a,true);boxes.forEach(c=>c.checked=true);toast(a.name+' adicionado à seleção')};
boxes.forEach(c=>c.onchange=()=>{const chosen=[...boxes].filter(c=>c.checked).map(c=>a.modules[+c.dataset.module]);if(chosen.length)selection.set(a.id,chosen);else selection.delete(a.id);sync()});
$('#go').onclick=$('#live').onclick=()=>openDemo(a)}
