function cheat(a){const secs=cheats[a.id]||[['Como funciona',a.steps.map(([t,d])=>`<b>${t}.</b> ${d}`)],['Recursos',a.chips],['Módulos',a.modules]],subs=tools.filter(t=>t.app===a.id).map(t=>t.name);
return `<aside class="cheat" aria-label="O que o ${a.name} faz"><span class="tag">COLINHA</span><h3>O que o ${a.name} faz</h3><p>${a.summary}</p>${secs.map(([h,l])=>`<h4>${h}</h4><ul>${l.map(i=>`<li>${i}</li>`).join('')}</ul>`).join('')}<h4>Para quem</h4><p>${a.audience}</p>${subs.length?`<h4>No lugar de</h4><p>${listPt.format(subs)}</p>`:''}</aside>`}
function openDemo(a){if(demo.dataset.app!==a.id){demo.dataset.app=a.id;demo.innerHTML=`<div class="bar"><span class="dots"><i></i><i></i><i></i></span><span class="url">${lock}${a.url}</span><button id="reload" aria-label="Recarregar ${a.name}">↻</button><a href="https://${a.url}" target="_blank" rel="noopener">Nova aba ↗</a><button class="close" aria-label="Fechar">×</button></div><div class="demo-body"><iframe title="${a.name} ao vivo" src="https://${a.url}" allow="fullscreen; clipboard-write"></iframe>${cheat(a)}</div><p class="note">Entre com o seu usuário para demonstrar. Se o login não se mantiver aqui dentro, use Nova aba.</p>`;$('#reload').onclick=()=>{demo.dataset.app='';openDemo(a)}}show(demo)}
